std::vector<std::uint32_t> ScriptSession::spellTargets(std::uint32_t source,const SpellInfo& s,WorldPoint point,unsigned owner) {
    std::vector<std::pair<float,std::uint32_t>> candidates;if(!alive(source,NativeKind::Unit))return {};auto caster=units_.at(source);for(auto& [id,u]:units_){float d=distance(*u,point);if(d<=s.area+u->collision && spellTarget(*caster,*u,s,false,owner))candidates.emplace_back(d,id);}std::sort(candidates.begin(),candidates.end());std::vector<std::uint32_t> result;for(auto [d,id]:candidates)result.push_back(id);return result;
}
Bytes ScriptSession::encodeAreaSpellState(const jass::StableHandleMap& encodeHandle) const {
    constexpr size_t budget=64u*1024u*1024u;if(!runtime_.snapshotSafe() || failed_ || !world_ || !setupApplied_ || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty() || spellWaves_.size()>4096 || delayedSpells_.size()>4096 || groundSpells_.size()>4096)throw std::runtime_error("Area spell snapshot requires a quiescent local session");SnapshotWriter out(budget-64);out.u32(tag("SASP"));out.u32(1);out.text(world_->resources().mapDigest(),64);out.u64(std::bit_cast<std::uint64_t>(simulationTime_));std::map<std::pair<NativeKind,std::uint32_t>,std::uint32_t> forward,reverse;auto stable=[&](std::uint32_t id,NativeKind kind){if(!id)return 0u;if(!encodeHandle || id<handleBase || id-handleBase>=objects_.size() || objects_[id-handleBase].kind!=kind)throw std::runtime_error("Invalid area spell reference");auto saved=encodeHandle(kind==NativeKind::Unit?"unit":"effect",id);auto [a,inserted]=forward.emplace(std::pair{kind,id},saved);auto [b,unique]=reverse.emplace(std::pair{kind,saved},id);if(!saved || (!inserted && a->second!=saved) || (!unique && b->second!=id))throw std::runtime_error("Invalid area spell mapping");return saved;};auto ref=[&](std::uint32_t id,NativeKind kind){out.u32(stable(id,kind));if(id)out.u32(objects_[id-handleBase].alive?1:0);};auto value=[&](float v){if(!std::isfinite(v))throw std::runtime_error("Invalid area spell value");out.u32(std::bit_cast<std::uint32_t>(v));};auto time=[&](double v){if(!std::isfinite(v) || v<0)throw std::runtime_error("Invalid area spell time");out.u64(std::bit_cast<std::uint64_t>(v));};auto point=[&](WorldPoint p){value(number(p.x));value(number(p.y));};auto ticket=[&](std::uint64_t id){if(!id || id>spellTicket_)throw std::runtime_error("Invalid area spell ticket");out.u64(id);};size_t refs=0;out.size(spellWaves_.size());for(auto& [id,w]:spellWaves_){if(!w.source || w.owner>=16 || w.hit.size()>65536 || w.hit.size()>262144-refs || w.travelled<0 || w.nextArt<0)throw std::runtime_error("Invalid spell wave");refs+=w.hit.size();ticket(id);writeSpellSnapshot(out,w.spell);ref(w.source,NativeKind::Unit);out.u32(w.owner);point(w.origin);value(w.directionX);value(w.directionY);value(w.travelled);value(w.dealt);value(w.nextArt);time(w.born);std::vector<std::pair<std::uint32_t,std::uint32_t>> hit;for(auto unit:w.hit)hit.emplace_back(stable(unit,NativeKind::Unit),unit);std::sort(hit.begin(),hit.end());out.size(hit.size());for(auto [saved,unit]:hit){if(!saved)throw std::runtime_error("Invalid spell wave target");ref(unit,NativeKind::Unit);}}out.size(delayedSpells_.size());for(auto& [id,d]:delayedSpells_){if(!d.source || d.owner>=16)throw std::runtime_error("Invalid delayed spell");ticket(id);writeSpellSnapshot(out,d.spell);ref(d.source,NativeKind::Unit);out.u32(d.owner);point(d.point);time(d.due);ref(d.target,NativeKind::Unit);}out.size(groundSpells_.size());for(auto& [id,g]:groundSpells_){if(!g.source || g.owner>=16 || g.spell.kind!=SpellKind::FlameStrike || g.spell.fullPeriod<=0 || g.spell.burnPeriod<=0 || g.visuals.size()>8192 || g.visuals.size()>262144-refs)throw std::runtime_error("Invalid ground spell");refs+=g.visuals.size();ticket(id);writeSpellSnapshot(out,g.spell);ref(g.source,NativeKind::Unit);out.u32(g.owner);point(g.point);time(g.elapsed);time(g.nextPulse);out.u32(g.started?1:0);out.u32(g.burn?1:0);out.size(g.visuals.size());for(auto effect:g.visuals){if(!effect)throw std::runtime_error("Invalid ground spell visual");ref(effect,NativeKind::Effect);}}return sealSnapshot(out.finish(),budget);
}
void ScriptSession::restoreAreaSpellState(std::span<const std::uint8_t> bytes,const jass::StableHandleMap& decodeHandle) {
    constexpr size_t budget=64u*1024u*1024u;if(!runtime_.ready() || failed_ || !world_ || !setupApplied_ || mainAttempted_ || !unitRecoveryIncomplete_ || !unitCoreFinished_ || areaSpellStateRestored_ || !spellWaves_.empty() || !delayedSpells_.empty() || !groundSpells_.empty() || runtime_.threadCount() || !runtime_.inspectExecutions().empty() || !contexts_.empty() || experimentalSelectionSync_ || !networkPlayers_.empty() || liveObjects(NativeKind::Event))throw std::runtime_error("Area spell restore requires rebuilt units and effects before events");Binary in(openSnapshot(bytes,budget));in.expect(tag("SASP"));if(in.u32()!=1 || snapshotText(in,64)!=world_->resources().mapDigest() || snapshotU64(in)!=std::bit_cast<std::uint64_t>(simulationTime_))throw std::runtime_error("Area spell map or clock differs");auto flag=[&]{auto v=in.u32();if(v>1)throw std::runtime_error("Invalid area spell flag");return v!=0;};std::map<std::pair<NativeKind,std::uint32_t>,std::uint32_t> reverse;auto ref=[&](NativeKind kind){auto saved=in.u32();if(!saved)return 0u;auto live=flag();auto id=decodeHandle?decodeHandle(kind==NativeKind::Unit?"unit":"effect",saved):0;auto& identities=kind==NativeKind::Unit?unitIdentityHandles_:effectIdentityHandles_;auto [it,unique]=reverse.emplace(std::pair{kind,id},saved);if(!id || !identities.contains(saved) || identities.at(saved)!=id || id<handleBase || id-handleBase>=objects_.size() || objects_[id-handleBase].kind!=kind || objects_[id-handleBase].alive!=live || (!unique && it->second!=saved))throw std::runtime_error("Invalid area spell mapping");return id;};auto value=[&]{auto v=std::bit_cast<float>(in.u32());if(!std::isfinite(v))throw std::runtime_error("Invalid area spell value");return v;};auto time=[&]{auto v=std::bit_cast<double>(snapshotU64(in));if(!std::isfinite(v) || v<0)throw std::runtime_error("Invalid area spell time");return v;};auto point=[&]{return WorldPoint{real(value()),real(value())};};std::set<std::uint64_t> tickets;auto ticket=[&]{auto id=snapshotU64(in);if(!id || id>spellTicket_ || !tickets.insert(id).second)throw std::runtime_error("Invalid area spell ticket");return id;};size_t refs=0;std::map<std::uint64_t,SpellWave> waves;auto count=in.count(4,4096);for(unsigned i=0;i<count;++i){auto id=ticket();SpellWave w;w.spell=readSpellSnapshot(in);w.source=ref(NativeKind::Unit);w.owner=in.u32();w.origin=point();w.directionX=value();w.directionY=value();w.travelled=value();w.dealt=value();w.nextArt=value();w.born=time();auto n=in.count(4,65536);if(!w.source || w.owner>=16 || w.travelled<0 || w.nextArt<0 || n>262144-refs)throw std::runtime_error("Invalid spell wave");refs+=n;for(unsigned j=0;j<n;++j){auto unit=ref(NativeKind::Unit);if(!unit || !w.hit.insert(unit).second)throw std::runtime_error("Invalid spell wave target");}waves.emplace(id,std::move(w));}std::map<std::uint64_t,DelayedSpell> delayed;count=in.count(4,4096);for(unsigned i=0;i<count;++i){auto id=ticket();DelayedSpell d;d.spell=readSpellSnapshot(in);d.source=ref(NativeKind::Unit);d.owner=in.u32();d.point=point();d.due=time();d.target=ref(NativeKind::Unit);if(!d.source || d.owner>=16)throw std::runtime_error("Invalid delayed spell");delayed.emplace(id,std::move(d));}std::map<std::uint64_t,GroundSpell> ground;count=in.count(4,4096);for(unsigned i=0;i<count;++i){auto id=ticket();GroundSpell g;g.spell=readSpellSnapshot(in);g.source=ref(NativeKind::Unit);g.owner=in.u32();g.point=point();g.elapsed=time();g.nextPulse=time();g.started=flag();g.burn=flag();auto n=in.count(4,8192);if(!g.source || g.owner>=16 || g.spell.kind!=SpellKind::FlameStrike || g.spell.fullPeriod<=0 || g.spell.burnPeriod<=0 || n>262144-refs)throw std::runtime_error("Invalid ground spell");refs+=n;for(unsigned j=0;j<n;++j){auto effect=ref(NativeKind::Effect);if(!effect)throw std::runtime_error("Invalid ground spell visual");g.visuals.push_back(effect);}ground.emplace(id,std::move(g));}in.finish();spellWaves_.swap(waves);delayedSpells_.swap(delayed);groundSpells_.swap(ground);areaSpellStateRestored_=true;
}
