void ScriptSession::areaSpell(std::uint32_t source,const SpellInfo& s,WorldPoint point,unsigned owner) {
    if(!alive(source,NativeKind::Unit))return;
    if(s.kind==SpellKind::Taunt){tauntSpell(source,s);return;}
    if(s.kind==SpellKind::HowlTerror || s.kind==SpellKind::Roar){roarEffect(source,s,owner);return;}
    if(wardSpell(s.kind)){summonSpell(source,s,point,owner);return;}
    if(s.kind==SpellKind::Silence){silenceEffect(source,s,point,owner);return;}
    if(s.kind==SpellKind::WarStomp && s.area>0 && requireWorld().canAddDeformation()){TerrainDeformation ripple;ripple.x=number(point.x);ripple.y=number(point.y);ripple.radius=s.area;ripple.depth=-50;ripple.duration=.3;ripple.count=1;ripple.spaceWaves=1;ripple.timeWaves=2;ripple.startRadius=1;ripple.limitNegative=true;ripple.started=simulationTime_;requireWorld().addDeformation(ripple);}
    if(s.kind==SpellKind::Dispel){auto targets=spellTargets(source,s,point,owner);for(auto target:targets){if(!alive(source,NativeKind::Unit))break;if(alive(target,NativeKind::Unit))dispelSpell(source,target,s);}spellVisual(s,"EffectArt",0,point);return;}
    if(s.kind==SpellKind::WaterElemental || s.kind==SpellKind::SpiritWolf || s.kind==SpellKind::SerpentWard || s.kind==SpellKind::Treants || s.kind==SpellKind::Scout || s.kind==SpellKind::VengeanceAvatar || s.kind==SpellKind::Grizzly || s.kind==SpellKind::Quilbeast || s.kind==SpellKind::Hawk || s.kind==SpellKind::LavaSpawn){summonSpell(source,s,point,owner);return;}
    auto victims=spellTargets(source,s,point,owner);float allocated=0;unsigned count=0;
    for(auto id:victims){
        if(!alive(source,NativeKind::Unit))break;if(!alive(id,NativeKind::Unit))continue;
        if(s.kind==SpellKind::FanKnives){if(s.targets && count>=s.targets)break;float amount=s.maxDamage>0?std::min(s.amount,std::max(0.f,s.maxDamage-allocated)):s.amount;if(amount<=0)break;allocated+=amount;++count;SpellMissile missile;missile.spell=s;missile.source=source;missile.target=id;missile.owner=owner;missile.position=point;missile.amount=amount;missile.born=simulationTime_;launchSpellMissile(std::move(missile));continue;}
        damageUnit(source,id,s.amount,0,14);if(s.kind==SpellKind::ThunderClap)applyBuff(id,source,s,BuffKind::Slow);else if(s.kind==SpellKind::WarStomp)applyBuff(id,source,s,BuffKind::Stun);else if(s.kind==SpellKind::Inferno){auto stun=s;stun.buff=ObjectData::code("BPSE");applyBuff(id,source,stun,BuffKind::Stun);}else throw std::runtime_error("Area spell consumer is missing");
    }
    if(s.kind==SpellKind::Inferno && alive(source,NativeKind::Unit))summonSpell(source,s,point,owner);spellVisual(s,"EffectArt",0,point);
}
void ScriptSession::areaSpellsTick(double delta) {
    std::vector<std::uint64_t> delayed,waves;for(auto& [id,s]:delayedSpells_)if(s.due<=simulationTime_)delayed.push_back(id);for(auto& [id,w]:spellWaves_)waves.push_back(id);
    for(auto id:delayed){auto found=delayedSpells_.find(id);if(found==delayedSpells_.end())continue;auto spell=std::move(found->second);delayedSpells_.erase(found);if(spell.target && spell.spell.kind==SpellKind::FingerOfDeath){if(alive(spell.source,NativeKind::Unit) && alive(spell.target,NativeKind::Unit)){auto source=units_.at(spell.source),target=units_.at(spell.target);SpellMissile visual;visual.spell=spell.spell;visual.source=spell.source;visual.target=spell.target;visual.owner=spell.owner;visual.position={source->x,source->y};spellLightning(visual);spellVisual(spell.spell,"TargetArt",spell.target,{target->x,target->y});}}else if(spell.target)manaBurn(spell.source,spell.target,spell.spell,spell.owner);else areaSpell(spell.source,spell.spell,spell.point,spell.owner);}
    for(auto id:waves){
        auto found=spellWaves_.find(id);if(found==spellWaves_.end())continue;auto wave=std::move(found->second);spellWaves_.erase(found);if(!alive(wave.source,NativeKind::Unit))continue;auto caster=units_.at(wave.source);auto& s=wave.spell;float previous=wave.travelled,next=std::min(s.distance,previous+float(delta)*s.speed);if(s.kind==SpellKind::Impale)impaleWaveArt(wave,next);std::vector<std::pair<float,std::uint32_t>> hits;
        for(auto& [target,u]:units_){if(wave.hit.contains(target))continue;float dx=number(u->x)-number(wave.origin.x),dy=number(u->y)-number(wave.origin.y),along=dx*wave.directionX+dy*wave.directionY;if(along<0 || along>s.distance+u->collision)continue;if(s.kind==SpellKind::Impale && (along+u->collision<previous || along-u->collision>next))continue;float closest=std::clamp(along,previous,next),radius=s.area+(s.endRadius-s.area)*std::clamp(along/s.distance,0.f,1.f);float x=dx-wave.directionX*closest,y=dy-wave.directionY*closest;if(x*x+y*y>(radius+u->collision)*(radius+u->collision) || !spellTarget(*caster,*u,s,false,wave.owner))continue;hits.emplace_back(along,target);}
        std::sort(hits.begin(),hits.end());for(auto [along,target]:hits){if(!alive(wave.source,NativeKind::Unit))break;if(!alive(target,NativeKind::Unit) || !spellTarget(*caster,*units_.at(target),s,false,wave.owner))continue;float amount=s.maxDamage>0?std::min(s.amount,std::max(0.f,s.maxDamage-wave.dealt)):s.amount;if(amount<=0 && s.kind!=SpellKind::Impale)break;wave.hit.insert(target);wave.dealt+=amount;if(s.kind==SpellKind::Impale)impaleHit(wave.source,target,s,wave.owner);else if(s.kind==SpellKind::BreathFire)breathFireHit(wave.source,target,s,wave.owner,amount);else damageUnit(wave.source,target,amount,0,14);}wave.travelled=next;
        if(next<s.distance && alive(wave.source,NativeKind::Unit) && (s.maxDamage<=0 || wave.dealt<s.maxDamage || s.kind==SpellKind::BreathFire))spellWaves_.emplace(id,std::move(wave));
    }
}
